fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of input rows
    let rows = x.len();
    // Number of input columns (since matrix is rectangular and non-empty)
    let cols = x[0].len();

    // Initialize the transposed matrix with "cols" rows,
    // each having "rows" elements
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(cols);
    for c in 0..cols {
        // For each column c in the input, create a new row in the output
        let mut new_row: Vec<f32> = Vec::with_capacity(rows);
        for r in 0..rows {
            new_row.push(x[r][c]);
        }
        result.push(new_row);
    }

    result
}